command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: EISENKRALLEN (RONDRA)
//
// - Ziel: Sich selbst, Zielkategorie Erwachte
// - temporäre Waffe 1W6+3 TP
// - Effektanlage direkt über Block 5
// - Wirkungsende zentral über Block 6
// - Wirkungskarte über Block 19.8
// - persistente Verknüpfung zwischen Effekt und Waffe
// - automatisches Löschen der Waffe beim Effektende
// - alte Effekte und Waffen werden sauber ersetzt
// ==========================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Eisenkrallen", vollerName = "Eisenkrallen (Rondra)", ahne = "Rondra";
    const waffenName = "Eisenkrallen (Temporär)", endeKey = "rondraEisenkrallen";
    const endeText =
        "Die Krallen verlieren ihren metallischen Glanz, werden wieder weich und die übernatürliche Waffe verschwindet.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - WAFFEN-CLEANUP-HOOK +++++++++++++++++++++++++++++

    if (globalThis._dskEisenkrallenCleanupHook) {
        Hooks.off("deleteActiveEffect", globalThis._dskEisenkrallenCleanupHook);
    }

    globalThis._dskEisenkrallenCleanupHook = Hooks.on("deleteActiveEffect", async effect => {
        if (!effect?.getFlag("dsk", "isEisenkrallen")) return;

        const actor = effect.parent;
        const linkedItemId = effect.getFlag("dsk", "linkedItemId");
        if (!actor || !linkedItemId) return;

        const waffe = actor.items?.get(linkedItemId);
        if (
            waffe &&
            waffe.getFlag("dsk", "isEisenkrallenWaffe") === true &&
            waffe.getFlag("dsk", "linkedEffectId") === effect.id
        ) {
            await waffe.delete();
        }
    });

    // +++ 4 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }
    };

    const findeEisenkrallenEffekte = actor => (actor?.effects || []).filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isEisenkrallen") === true
    );

    const findeEisenkrallenWaffen = actor => (actor?.items || []).filter(item =>
        item.getFlag("dsk", "isEisenkrallenWaffe") === true ||
        item.name === waffenName
    );

    // +++ 5 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Eisenkrallen Probe", "Eisenkrallen"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const dauerRunden = qs * 3;
    const dauerText = `${dauerRunden} Kampfrunde(n) (${qs} QS × 3 KR)`;
    const basisBeschreibung =
        `Die Krallen des Rondrakindes verhärten sich und glänzen metallisch. ` +
        `Während der Wirkungsdauer verursacht das Rondrakind mit seinen Krallen ` +
        `<b>1W6+3 TP</b> im Nahkampf.` +
        `<br><br><b>Zielkategorie:</b> Erwachte`;

    // +++ 6 - ZIELKATEGORIE VORHER PRÜFEN +++++++++++++++++++++

    if (!DSK_FW.Effekt.CheckTarget(casterActor, "erwachte")) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
            wirkender: casterName, ziele: [],
            misserfolge: [{ name: casterName, grund: "Kein Erwachter" }],
            dauerText, gmBereich: false,
            angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 7 - ALTE EFFEKTE UND WAFFEN ENTFERNEN +++++++++++++++

    const alteEffekte = findeEisenkrallenEffekte(casterActor);

    for (const effect of alteEffekte) {
        const linkedItemId = effect.getFlag("dsk", "linkedItemId");
        const alteWaffe = linkedItemId ? casterActor.items.get(linkedItemId) : null;
        if (alteWaffe) await alteWaffe.delete();
        await effect.delete();
    }

    const alteWaffen = findeEisenkrallenWaffen(casterActor);
    if (alteWaffen.length) {
        await casterActor.deleteEmbeddedDocuments("Item", alteWaffen.map(item => item.id));
    }

    // +++ 8 - TEMPORÄRE WAFFE ERZEUGEN ++++++++++++++++++++++++

    const itemData = {
        name: waffenName, type: "meleeweapon",
        img: "systems/dsk/assets/icons/categories/meleeweapon.webp",
        system: {
            combatskill: "Raufen", tp: "1d6+3", rw: "short",
            worn: { value: true, wearable: true, wrongGrip: false },
            price: 0, weight: 0, quantity: 1
        },
        flags: { dsk: {
            isEisenkrallenWaffe: true,
            casterUuid: casterActor.uuid,
            qs
        }}
    };

    const [createdItem] = await casterActor.createEmbeddedDocuments("Item", [itemData]);

    if (!createdItem) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die temporäre Eisenkrallen-Waffe konnte nicht erstellt werden!");
    }

    // +++ 9 - EFFEKT DIREKT ÜBER BLOCK 5 ++++++++++++++++++++++

    const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne,
        beschreibung: basisBeschreibung + `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
        gabeZiel: "erwachte", qs, ziel: casterActor,
        duration: { rounds: dauerRunden, startTime: game.time.worldTime },
        showIcon: 2,
        flags: { dsk: {
            isEisenkrallen: true, casterUuid: casterActor.uuid,
            linkedItemId: createdItem.id, qs,
            wirkungsende: {
                sfName: endeKey, basisEffektName: vollerName,
                beschreibungFuerEnde: endeText
            }
        }}
    });

    if (!erzeugterEffekt) {
        await createdItem.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Der Eisenkrallen-Effekt konnte nicht angelegt werden!");
    }

    // Effekt-ID nachträglich an der temporären Waffe speichern.
    await createdItem.update({
        "flags.dsk.linkedEffectId": erzeugterEffekt.id
    });

    // +++ 10 - EFFEKT UND VERKNÜPFUNG KONTROLLIEREN ++++++++++++

    const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");
    const effektErfolgreich =
        (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
        erzeugterEffekt.getFlag("dsk", "isEisenkrallen") === true &&
        erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        erzeugterEffekt.getFlag("dsk", "linkedItemId") === createdItem.id &&
        Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName;

    const waffeErfolgreich =
        createdItem.getFlag("dsk", "isEisenkrallenWaffe") === true &&
        createdItem.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        createdItem.getFlag("dsk", "linkedEffectId") === erzeugterEffekt.id;

    if (!effektErfolgreich || !waffeErfolgreich) {
        const schluessel = erzeugterEffekt.uuid || `${casterActor.uuid}.${erzeugterEffekt.id}`;

        try {
            await erzeugterEffekt.delete();
        } finally {
            if (casterActor.items.get(createdItem.id)) await createdItem.delete();
        }

        console.warn("Eisenkrallen: Unvollständige Effekt-/Waffenverknüpfung.", {
            schluessel, effektErfolgreich, waffeErfolgreich
        });

        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Eisenkrallen wurde nicht vollständig angelegt!");
    }

    // +++ 11 - WIRKUNGSKARTE ÜBER BLOCK 19.8 ++++++++++++++++++

    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung, wirkender: casterName,
        ziele: [{ name: casterName, rolle: `Erhält Waffe: ${waffenName}` }],
        misserfolge: [], dauerText,
        gmBereich: false, angewendet: true, erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    // +++ 12 - QS AUFRÄUMEN ++++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
